<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowUpRight, ArrowRight, Check, ChevronRight, Clock3, FileText, Landmark, Link2, ListChecks, ScanText, ShieldCheck, Sparkles } from 'lucide-vue-next'
import { usePlatformStore } from '../stores/platform'
import { DEMO_DATE } from '../mock/data'
import StatusBadge from '../components/StatusBadge.vue'
import Modal from '../components/Modal.vue'
const store = usePlatformStore(), router = useRouter()
const range = ref<'7天' | '本月'>('7天'), queueTab = ref<'待处理' | '核查任务'>('待处理'), showQueue = ref(false), selectedDate = ref(DEMO_DATE)
const money = (n:number) => n.toLocaleString('zh-CN')
const contract = computed(() => store.contracts.find(c => c.id === 'SZ-HT-2026-018')!)
const finding = computed(() => store.findings.find(f => f.sourceId === contract.value.id)!)
const receipts = computed(() => store.payments.filter(p => p.contractId === contract.value.id))
const received = computed(() => receipts.value.reduce((s,p) => s + p.amount, 0))
const difference = computed(() => Math.max(0,contract.value.receivable - received.value))
const linkedClues = computed(() => store.clues.filter(c => c.content.includes(contract.value.id)))
const pathFor:Record<string,string> = {'信访线索':'/clues','农村三资':'/assets','巡察整改':'/inspection','AI助手':'/assistant'}
type WorkItem = { id:string; title:string; source:string; area:string; priority:string; status:string; path:string; sourceId:string }
const pending = computed<WorkItem[]>(() => [
  ...store.clues.filter(c => ['待研判','待人工确认','待复核'].includes(c.status)).map(c => ({...c,source:'信访线索',path:'/clues',sourceId:c.id})),
  ...store.findings.filter(f => f.status === '待核查').map(f => ({...f,source:'农村三资',path:'/assets',sourceId:f.id})),
  ...store.issues.filter(i => ['待整改','待复核'].includes(i.status)).map(i => ({...i,source:'巡察整改',priority:'优先核查',path:'/inspection',sourceId:i.id})),
].sort((a,b) => ['高关注','优先核查','一般关注'].indexOf(a.priority)-['高关注','优先核查','一般关注'].indexOf(b.priority)))
const queue = computed<WorkItem[]>(() => queueTab.value === '待处理' ? pending.value : store.tasks.map(t => ({...t,path:pathFor[t.source] || '/',sourceId:t.sourceId})))
const queuePreview = computed(() => {
  if(queueTab.value==='核查任务') return queue.value.slice(0,3)
  const seen = new Set<string>()
  return queue.value.filter(item => {
    const key = item.id===finding.value.id || linkedClues.value.some(c=>c.id===item.id) ? contract.value.id : item.id
    if(seen.has(key)) return false
    seen.add(key);return true
  }).slice(0,3)
})
function open(item:WorkItem) { showQueue.value=false; router.push({path:item.path,query:{id:item.sourceId}}) }
function go(path:string,id?:string) { router.push({path,query:id?{id}:{}}) }
const queues = computed(() => [
  {name:'信访待研判',count:store.clues.filter(c=>c.status==='待研判').length,unit:'条线索',path:'/clues',icon:FileText,tone:'blue'},
  {name:'三资待核查',count:store.findings.filter(f=>f.status==='待核查').length,unit:'项疑点',path:'/assets',icon:Landmark,tone:'teal'},
  {name:'巡察待阅卷',count:store.issues.filter(i=>i.status==='待阅卷').length,unit:'份材料',path:'/inspection',icon:ScanText,tone:'slate'},
])
const completed = computed(() => store.tasks.filter(t=>t.status==='已完成').length)
const taskProgress = computed(() => store.tasks.length ? Math.round(completed.value/store.tasks.length*100) : 0)
const dates = computed(() => {
  const end = new Date(DEMO_DATE+'T12:00:00Z')
  const count = range.value==='7天' ? 7 : end.getUTCDate()
  return Array.from({length:count},(_,i) => {const d=new Date(end);d.setUTCDate(end.getUTCDate()-count+1+i);return d.toISOString().slice(0,10)})
})
const trend = computed(() => dates.value.map(date => ({date,label:`${Number(date.slice(5,7))}/${Number(date.slice(8))}`,clues:store.clues.filter(c=>c.date.slice(0,10)===date).length,created:store.tasks.filter(t=>t.createdAt.slice(0,10)===date).length,done:store.tasks.filter(t=>t.status==='已完成'&&(t.completedAt||t.createdAt).slice(0,10)===date).length})))
const ceiling = computed(() => {const peak=Math.max(0,...trend.value.flatMap(d=>[d.clues,d.created,d.done]));return Math.max(2,Math.ceil((peak+1)/2)*2)})
const periodClues = computed(() => trend.value.reduce((s,d)=>s+d.clues,0))
const periodTasks = computed(() => trend.value.reduce((s,d)=>s+d.created,0))
const periodDone = computed(() => trend.value.reduce((s,d)=>s+d.done,0))
const activeDay = computed(() => trend.value.find(d=>d.date===selectedDate.value)||trend.value[trend.value.length-1]!)
const barHeight = (value:number) => `${value/ceiling.value*100}%`
const dateLabel = computed(() => {const d=new Date(DEMO_DATE+'T12:00:00Z');return d.toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'})})
</script>

<template>
<div class="supervision-overview">
  <header class="overview-title"><div><div class="context-label"><span></span>县域智能监督工作台</div><h1>监督工作总览</h1></div><div class="overview-context"><span>{{dateLabel}} <b>演示数据</b></span><div class="quick-summary"><span><strong>{{store.metrics.highPriorityClues}}</strong>高关注线索</span><span><strong>{{store.metrics.activeTasks}}</strong>在办任务</span><span><strong>{{completed}}</strong>核查完成</span></div></div></header>

  <div class="decision-grid">
    <section class="focus-case" aria-label="重点监督事项">
      <div class="focus-top"><span class="focus-kicker"><span></span>重点监督事项 <b>/</b> 农村集体资产</span><span class="focus-state"><i :class="finding.status==='已完成'?'done':''"></i>{{finding.status==='待核查'?'待人工核查':finding.status}}</span></div>
      <div class="case-heading"><div><h2>{{contract.asset}}<span>到账关联待核对</span></h2><p>{{contract.area}} <span>·</span> {{contract.id}}</p></div><button class="evidence-count" @click="go('/clues',linkedClues[0]?.id)" aria-label="查看关联信访材料"><Link2 :size="19"/><strong>{{linkedClues.length}}</strong><span>份关联线索</span><ArrowUpRight :size="15"/></button></div>
      <div class="funding-equation"><div><span>合同约定应收</span><strong>{{money(contract.receivable)}}<small>元</small></strong></div><span class="equation-mark">−</span><div><span>已关联到账</span><strong>{{money(received)}}<small>元</small></strong></div><span class="equation-mark">=</span><div class="funding-gap"><span>待核对差额</span><strong>{{money(difference)}}<small>元</small></strong></div></div>
      <div class="evidence-trail"><button @click="go('/assets',contract.id)"><FileText :size="15"/><span>合同原始条款</span><Check :size="13"/></button><ChevronRight :size="13"/><button @click="go('/assets',contract.id)"><ListChecks :size="15"/><span>{{receipts.length}} 笔收款记录</span><Check :size="13"/></button><ChevronRight :size="13"/><span class="trail-pending"><ShieldCheck :size="15"/>人工核实</span></div>
      <div class="focus-bottom"><p>差额可能涉及未录入收款，现有材料不作事实认定。</p><button class="focus-action" @click="go('/assets',finding.id)">{{finding.status==='已完成'?'查看核查记录':'查看证据，进入核查'}}<ArrowRight :size="17"/></button></div>
    </section>

    <section class="action-queue" aria-label="监督待办队列"><div class="queue-heading"><h2>接下来，优先处理</h2><span class="queue-total">{{pending.length}}<small>条待办记录</small></span></div><div class="queue-tabs"><button :class="{active:queueTab==='待处理'}" @click="queueTab='待处理'">待处理事项 <span>{{pending.length}}</span></button><button :class="{active:queueTab==='核查任务'}" @click="queueTab='核查任务'">核查任务 <span>{{store.tasks.length}}</span></button></div>
      <div class="queue-list"><button v-for="(item,index) in queuePreview" :key="item.id" class="queue-row" @click="open(item)"><span class="queue-rank">{{String(index+1).padStart(2,'0')}}</span><div><span class="queue-source"><span>{{item.source}}</span><span class="queue-id">{{item.id}}</span><span class="queue-state">{{item.status}}</span></span><h3>{{item.title}}</h3></div><ArrowUpRight :size="17"/></button><div v-if="!queue.length" class="queue-empty"><ShieldCheck :size="28"/><h3>{{queueTab==='核查任务'?'任务从人工确认开始':'待办已处理完毕'}}</h3><p>{{queueTab==='核查任务'?'在研判或核查场景中确认后，任务将同步到这里。':'可查看已形成的核查任务与办理进展。'}}</p></div></div>
      <button class="queue-all" @click="showQueue=true"><span class="queue-all-label">查看全部{{queueTab==='待处理'?'待办记录':'核查任务'}}<small v-if="queueTab==='待处理'">优先展示 {{queuePreview.length}} 组关联事项</small></span><span>{{queue.length}} <ArrowRight :size="15"/></span></button>
    </section>
  </div>

  <div class="analysis-grid">
    <section class="business-pulse" aria-label="线索与任务流转"><div class="analysis-heading"><div><h2>线索进入与任务流转</h2><p>登记 {{periodClues}} 条线索 · 新建 {{periodTasks}} 项任务 · 完成 {{periodDone}} 项核查</p></div><div class="period-switch"><button v-for="r in (['7天','本月'] as const)" :key="r" :class="{active:range===r}" @click="range=r">{{r==='7天'?'最近 7 天':'本月'}}</button></div></div><div class="chart-legend"><span><i class="clue-color"></i>线索登记</span><span><i class="task-color"></i>任务创建</span><span><i class="done-color"></i>核查完成</span><small>单位：条 / 项</small></div>
      <div class="business-chart"><div class="chart-scale"><span>{{ceiling}}</span><span>{{Math.round(ceiling/2)}}</span><span>0</span></div><div class="chart-grid"><div class="grid-line top"></div><div class="grid-line middle"></div><div class="grid-line bottom"></div><div class="chart-days" :style="{'--days':trend.length}"><button v-for="day in trend" :key="day.date" class="chart-day" :class="{selected:activeDay.date===day.date}" @click="selectedDate=day.date" :aria-label="`${day.label}，登记${day.clues}条，创建${day.created}项，完成${day.done}项`"><span class="day-bars"><span class="bar clue-color" :class="{zero:!day.clues}" :style="{height:barHeight(day.clues)}"><b v-if="day.clues">{{day.clues}}</b></span><span class="bar task-color" :class="{zero:!day.created}" :style="{height:barHeight(day.created)}"><b v-if="day.created">{{day.created}}</b></span><span class="bar done-color" :class="{zero:!day.done}" :style="{height:barHeight(day.done)}"><b v-if="day.done">{{day.done}}</b></span></span><span class="day-label">{{day.label}}</span></button></div></div></div>
      <div class="chart-explanation"><span><i></i>{{activeDay.label}}：登记 <strong>{{activeDay.clues}}</strong> 条，创建 <strong>{{activeDay.created}}</strong> 项，完成 <strong>{{activeDay.done}}</strong> 项</span><span>按业务日期统计，三类数量独立计算</span></div>
    </section>
    <section class="supervision-queues" aria-label="业务队列与核查进度"><div class="analysis-heading"><h2>监督业务队列</h2><span class="split-caption">按来源分列</span></div><div class="domain-rows"><button v-for="item in queues" :key="item.name" class="domain-row" @click="go(item.path)"><component :is="item.icon" :size="19"/><div class="domain-main"><div><span>{{item.name}}</span><strong>{{item.count}}<small>{{item.unit}}</small></strong></div></div><ArrowUpRight :size="15"/></button></div><div class="verification-progress"><div><span><ShieldCheck :size="16"/>人工核查进度</span><strong>{{completed}}<small>/ {{store.tasks.length}} 项完成</small></strong></div><div class="verification-track"><span :style="{width:`${taskProgress}%`}"></span></div><p>{{store.tasks.length?`另有 ${store.metrics.activeTasks} 项任务正在办理`:'任务须经人工确认后发起'}}<span>来源记录可关联同一事项</span></p></div></section>
  </div>

  <div class="business-entry-bar"><div><Sparkles :size="17"/><strong>从材料到闭环</strong><span>让每一次辅助分析，都落到有依据的人工核查。</span></div><nav aria-label="核心业务入口"><button @click="go('/clues')">信访研判<ArrowUpRight :size="15"/></button><button @click="go('/assets')">三资穿透<ArrowUpRight :size="15"/></button><button @click="go('/inspection')">巡察整改<ArrowUpRight :size="15"/></button></nav></div>

  <Modal v-if="showQueue" :title="queueTab==='待处理'?'全部待办记录':'核查任务'" @close="showQueue=false"><p class="all-queue-note">关联记录可反映同一事项，所有关键处置均由人工确认。</p><button v-for="item in queue" :key="item.id" class="all-queue-row" @click="open(item)"><div><span>{{item.source}} · {{item.id}}</span><h3>{{item.title}}</h3><p>{{item.area}}</p></div><StatusBadge :status="item.status"/><ArrowUpRight :size="17"/></button><div v-if="!queue.length" class="empty">暂无核查任务，请在业务工作台中人工确认后创建。</div></Modal>
</div>
</template>

<style scoped>
